'use strict';
(()=>{let catalog=[],rows=[],total=0,offset=0,preview=null,editing=null,busy=false;const selected=new Set(),filters={business:'platform',q:'',card:'',branch:'',consent:'',archived:''};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={unknown:'غير مسجلة',opted_in:'موافقة سابقة مسجلة',opted_out:'أوقف الرسائل'};
const root=()=>document.querySelector('#marketing-contacts-root'),say=t=>document.querySelector('#marketing-alert').textContent=t;
async function api(path,body){const r=await fetch('/api/marketing/'+path,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'تعذر تنفيذ الطلب.');return d;}
const opts=(items,value,empty)=>`<option value="">${empty}</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('');
const businessCards=()=>catalog.filter(x=>x.business===filters.business),branches=()=>businessCards().flatMap(x=>x.branches),businesses=()=>catalog.filter(x=>x.id===x.business);
const label=(ids,type)=>ids.map(id=>(type==='cards'?catalog:catalog.flatMap(c=>c.branches)).find(x=>x.id===id)?.name||'غير متاح').join('، ')||'—';
const field=(name,title,value='',extra='')=>`<label>${title}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
function form(){const c=editing||{name:'',phone:'',notes:'',consent:'unknown',cards:filters.card?[filters.card]:[],branches:filters.branch?[filters.branch]:[]};return `<section class="marketing-panel"><h2>${editing?'تعديل جهة الاتصال':'إضافة رقم'}</h2><p>جهة الاتصال مستقلة. ربطها ببطاقة الولاء أو فرع اختياري ولا يصدر بطاقة للعميل.</p><form id="marketing-contact-save">${field('name','اسم العميل',c.name,'maxlength="100"')}${field('phone','رقم الجوال',c.phone,'required dir="ltr" placeholder="05… أو الرقم الدولي" '+(editing?'readonly':''))}<label>بطاقات الولاء · اختياري<select name="cards" multiple size="3">${businessCards().map(x=>`<option value="${esc(x.id)}" ${c.cards.includes(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>الفروع · اختياري<select name="branches" multiple size="3">${branches().map(x=>`<option value="${esc(x.id)}" ${c.branches.includes(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>حالة استقبال الرسائل<select name="consent">${Object.entries(labels).map(([v,t])=>`<option value="${v}" ${c.consent===v?'selected':''}>${t}</option>`).join('')}</select></label>${field('consentProof','مصدر الموافقة السابقة · عند تسجيلها',c.consentProof,'maxlength="300" placeholder="مثل موافقة مسجلة في نظام النشاط"')}<label>ملاحظات<textarea name="notes" maxlength="600">${esc(c.notes)}</textarea></label><div class="marketing-actions"><button class="info-button gold">حفظ جهة الاتصال</button>${editing?'<button type="button" class="info-button" data-contact="cancel-edit">إلغاء التعديل</button>':''}</div></form></section>`;}
function importer(){return `<section class="marketing-panel"><h2>استيراد جهات الاتصال</h2><p>ارفع XLSX من نظامك الخارجي أو استخدم النموذج. الأعمدة: name وphone وnotes. حتى 1000 صف و2 ميجابايت. اختَر النشاط والبطاقة والفرع في التصفية أولًا لتصنيف الأرقام المستوردة.</p><div class="marketing-actions"><button class="info-button" data-contact="template">تنزيل نموذج إكسل</button><button class="info-button" data-contact="loyalty" ${filters.business==='platform'?'disabled':''}>جلب عملاء رجعة</button></div><form id="marketing-contact-file"><label>ملف إكسل<input name="file" type="file" accept=".xlsx" required></label><label><input type="checkbox" name="consentProvided"> لدي موافقة سابقة مسجلة لهذه القائمة</label>${field('consentProof','مصدر الموافقة السابقة','','maxlength="300"')}<button class="info-button gold">معاينة الاستيراد</button></form>${preview?`<div class="contact-import-review"><h3>مراجعة الملف</h3><p>${preview.summary.new} جديد · ${preview.summary.existing} موجود · ${preview.summary.duplicate} مكرر · ${preview.summary.invalid} غير صحيح. الصفوف غير الصحيحة والمكررة تُستبعد، والموجودة تُدمج دون تكرار الرقم.</p><div class="contact-table-wrap"><table class="marketing-table"><thead><tr><th>الصف</th><th>الاسم</th><th>الرقم</th><th>النتيجة</th></tr></thead><tbody>${preview.rows.slice(0,100).map(r=>`<tr><td>${r.row}</td><td>${esc(r.name)}</td><td dir="ltr">${esc(r.phone)}</td><td>${esc(r.error||({new:'جديد',existing:'دمج مع الموجود',duplicate:'مكرر',invalid:'غير صحيح'})[r.status])}</td></tr>`).join('')}</tbody></table></div>${preview.rows.length>100?'<p>تُعرض أول 100 نتيجة؛ الملخص يشمل الملف كاملًا.</p>':''}<button class="info-button gold" data-contact="import" ${preview.summary.new+preview.summary.existing===0?'disabled':''}>تأكيد استيراد الأرقام الصالحة</button></div>`:''}</section>`;}
function render(){if(!root())return;root().innerHTML=`<section class="marketing-panel"><h2>الأرقام وجهات الاتصال</h2><p>أرقام رجعة وأرقام من أنظمة خارجية، في قوائم مستقلة لكل نشاط. لا تُرسل رسالة عند الإضافة أو الاستيراد.</p><div class="contact-filter-grid"><label>النشاط<select data-contact-filter="business"><option value="platform" ${filters.business==='platform'?'selected':''}>أرقام مستقلة · إدارة رجعة</option>${businesses().map(x=>`<option value="${esc(x.id)}" ${filters.business===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>بطاقة الولاء<select data-contact-filter="card">${opts(businessCards(),filters.card,'جميع البطاقات')}</select></label><label>الفرع<select data-contact-filter="branch">${opts(branches(),filters.branch,'جميع الفروع')}</select></label><label>حالة الرسائل<select data-contact-filter="consent"><option value="">جميع الحالات</option>${Object.entries(labels).map(([v,t])=>`<option value="${v}" ${filters.consent===v?'selected':''}>${t}</option>`).join('')}</select></label><label>القائمة<select data-contact-filter="archived"><option value="">النشطة</option><option value="yes" ${filters.archived==='yes'?'selected':''}>المؤرشفة</option></select></label></div><form id="marketing-contact-search"><label>بحث<input name="q" value="${esc(filters.q)}" placeholder="الاسم أو الرقم أو الملاحظات"></label><button class="info-button">بحث</button></form><div class="marketing-actions"><button class="info-button" data-contact="export">تصدير القائمة إلى إكسل</button><button class="info-button" data-contact="campaign">إعداد حملة للمحدد (${selected.size})</button></div><p>${total} جهة اتصال في النطاق · ${selected.size} محددة</p><div class="contact-table-wrap"><table class="marketing-table"><thead><tr><th><input type="checkbox" data-contact-select="all" aria-label="تحديد أرقام الصفحة" ${rows.length&&rows.every(c=>selected.has(c.id))?'checked':''}></th><th>العميل</th><th>الجوال</th><th>البطاقات</th><th>الفروع</th><th>الرسائل</th><th>الإدارة</th></tr></thead><tbody>${rows.map(c=>`<tr><td><input type="checkbox" data-contact-select="${esc(c.id)}" aria-label="تحديد ${esc(c.name||c.phone)}" ${selected.has(c.id)?'checked':''}></td><td>${esc(c.name||'—')}</td><td dir="ltr">${esc(c.phone)}</td><td>${esc(label(c.cards,'cards'))}</td><td>${esc(label(c.branches,'branches'))}</td><td>${labels[c.consent]||'غير مسجلة'}</td><td><button class="info-button" data-contact="edit" data-id="${esc(c.id)}">تعديل</button><button class="info-button" data-contact="archive" data-id="${esc(c.id)}">${c.archived?'استعادة':'أرشفة'}</button></td></tr>`).join('')||'<tr><td colspan="7">لا توجد أرقام في هذا النطاق.</td></tr>'}</tbody></table></div><div class="marketing-actions"><button class="info-button" data-contact="prev" ${offset===0?'disabled':''}>السابق</button><span>${total?Math.floor(offset/100)+1:0} / ${Math.ceil(total/100)}</span><button class="info-button" data-contact="next" ${offset+100>=total?'disabled':''}>التالي</button></div></section><div class="marketing-grid">${form()}${importer()}</div>`;}
async function load(){const q=new URLSearchParams({...filters,offset:String(offset)});const d=await api('contacts?'+q);rows=d.contacts;total=d.total;catalog=d.catalog;render();}
async function run(fn){if(busy)return;busy=true;try{await fn();}catch(e){say(e.message);}finally{busy=false;}}
async function download(kind){const d=await api(kind,{...filters,selected:kind==='contact-export'?[...selected]:[]});const bytes=Uint8Array.from(atob(d.file),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download=d.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const review=async b=>{preview=await api('contact-preview',{...filters,cards:filters.card?[filters.card]:[],branches:filters.branch?[filters.branch]:[],...b});render();say('راجع النتائج ثم أكد الاستيراد.');};
document.addEventListener('change',e=>{if(!root()?.contains(e.target))return;const filter=e.target.dataset.contactFilter;if(filter){filters[filter]=e.target.value;if(filter==='business'){filters.card='';filters.branch='';}offset=0;selected.clear();editing=null;preview=null;run(load);}const id=e.target.dataset.contactSelect;if(id){for(const key of id==='all'?rows.map(c=>c.id):[id])e.target.checked?selected.add(key):selected.delete(key);const b=root().querySelector('[data-contact=campaign]');b.textContent='إعداد حملة للمحدد ('+selected.size+')';}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-contact]');if(!b||!root()?.contains(b)||b.disabled)return;const a=b.dataset.contact;run(async()=>{if(a==='edit'){editing=rows.find(c=>c.id===b.dataset.id);render();root().querySelector('#marketing-contact-save input').focus();}if(a==='cancel-edit'){editing=null;render();}if(a==='archive'){const c=rows.find(x=>x.id===b.dataset.id);await api('contact-archive',{business:filters.business,id:c.id,archived:!c.archived});selected.delete(c.id);await load();say(c.archived?'تمت استعادة الرقم.':'تمت أرشفة الرقم.');}if(a==='template'||a==='export')await download(a==='template'?'contact-template':'contact-export');if(a==='loyalty')await review({fromLoyalty:true});if(a==='import'){await api('contact-import',{business:filters.business,id:preview.id,confirm:true});preview=null;await load();say('تم استيراد جهات الاتصال دون إرسال رسائل.');}if(a==='next'||a==='prev'){offset+=a==='next'?100:-100;await load();}if(a==='campaign'){if(!selected.size)throw Error('حدد أرقامًا من القائمة أولًا.');document.dispatchEvent(new CustomEvent('marketing-audience',{detail:{...filters,selected:[...selected]}}));}});});
document.addEventListener('submit',e=>{if(!root()?.contains(e.target))return;e.preventDefault();const f=e.target,d=new FormData(f);run(async()=>{if(f.id==='marketing-contact-search'){filters.q=String(d.get('q')||'');offset=0;selected.clear();await load();}if(f.id==='marketing-contact-save'){await api('contact-save',{business:filters.business,...(editing?{id:editing.id}:{}),name:d.get('name'),phone:d.get('phone'),notes:d.get('notes'),consent:d.get('consent'),consentProof:d.get('consentProof'),cards:d.getAll('cards'),branches:d.getAll('branches')});editing=null;await load();say('تم حفظ جهة الاتصال دون إرسال.');}if(f.id==='marketing-contact-file'){const file=d.get('file');if(!file?.name.endsWith('.xlsx')||file.size>2*1024*1024)throw Error('اختر ملف XLSX حتى 2 ميجابايت.');const raw=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<raw.length;i+=8192)text+=String.fromCharCode(...raw.subarray(i,i+8192));await review({file:btoa(text),consentProvided:d.get('consentProvided')==='on',consentProof:d.get('consentProof')});}});});
window.MarketingContacts={html:()=>'<div id="marketing-contacts-root">جارٍ تحميل الأرقام…</div>',load};})();
